div.script:
(function () {
    const KEY = 'bw_offline_punches_v1';
    const CSRF = document.querySelector('input[name="csrf_token"]')?.value || '';
    function readQ() {
        try { return JSON.parse(localStorage.getItem(KEY) || '[]'); } catch (e) { return []; }
    }
    function writeQ(q) { localStorage.setItem(KEY, JSON.stringify(q)); }
    function pushAction(direction) {
        const q = readQ();
        q.push({ direction: direction, time: new Date().toISOString() });
        writeQ(q);
        const el = document.getElementById('bw_offline_status');
        if (el) el.textContent = 'Queued ' + q.length + ' action(s).';
    }
    document.querySelectorAll('form[action="/my/berkeley_workforce/punch"]').forEach(function (form) {
        form.addEventListener('submit', function (ev) {
            if (!navigator.onLine) {
                ev.preventDefault();
                const dir = form.querySelector('input[name="direction"]').value;
                pushAction(dir);
            }
        });
    });
    const btn = document.getElementById('bw_offline_sync_btn');
    if (btn) {
        btn.addEventListener('click', function () {
            const q = readQ();
            if (!q.length) {
                document.getElementById('bw_offline_status').textContent = 'Nothing to sync.';
                return;
            }
            const body = new URLSearchParams();
            body.append('csrf_token', CSRF);
            body.append('punches_json', JSON.stringify(q));
            fetch('/my/berkeley_workforce/sync', {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: body.toString(),
                credentials: 'same-origin',
            }).then(function (r) { return r.json(); }).then(function (data) {
                if (data && data.ok) {
                    writeQ([]);
                    document.getElementById('bw_offline_status').textContent = 'Synced ' + data.processed + ' action(s). Reloading…';
                    window.location.reload();
                } else {
                    document.getElementById('bw_offline_status').textContent = 'Sync failed.';
                }
            }).catch(function () {
                document.getElementById('bw_offline_status').textContent = 'Sync failed (network).';
            });
        });
    }
})();
